hermes_script:
#!/bin/sh
log="$FAKE_HERMES_LOG"
{
  printf 'argc=%s\n' "$#"
  for a in "$@"; do printf 'arg<<%s>>\n' "$a"; done
} >> "$log"
case "$FAKE_HERMES_MODE" in
  ok) printf 'Answer from <hermes> [[alpha.md]]\n' ;;
  warn) printf 'Findings.\n\n## Sources\n- [[notes/outside.md]]\n- [[alpha.md]]\n' ;;
  fail) printf 'hermes exploded\n' >&2; exit 4 ;;
  *) exit 9 ;;
esac

